const j = $json;
const pick = (label, idx) => String(j[label] ?? j[`field-${idx}`] ?? '').trim();

const videoUrl = pick('videoUrl', 0);
const title = pick('title', 1);
const rawDescription = pick('description', 2);
const thumbUrl = pick('thumbUrl', 3);

if (!/^https:\/\//.test(videoUrl)) {
  throw new Error(`videoUrl must be a public https URL, got: ${videoUrl || '(empty)'}`);
}
if (!title) throw new Error('title is empty.');
if (thumbUrl && !/^https:\/\//.test(thumbUrl)) {
  throw new Error(`thumbUrl must be a public https URL if given, got: ${thumbUrl}`);
}

// A YouTube description is written for YouTube: hook, then the article link,
// then a second summary, chapters, and a repeat of the link. Pasting all of it
// under a Facebook video buries the one line a reader acts on and prints the
// same URL twice. Facebook gets the first paragraph and the link, nothing else.
//
// The trim happens here rather than at the caller so it cannot be forgotten:
// the workflow is handed the full YouTube description and decides what to post.
function trimForFacebook(text) {
  if (!text) return '';
  const paragraphs = text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
  const first = paragraphs[0] ?? '';

  // Carry the link's own line verbatim rather than relabelling it. An article
  // video says "Full article: <url>"; a sound session says "More at <url>" and
  // has no article behind it, so printing "Full article" there would be a lie.
  // Prefer the labelled form because these descriptions repeat the same URL at
  // the bottom under different wording, and the first one is canonical.
  const lines = text.split('\n').map((l) => l.trim());
  const linkLine =
    lines.find((l) => /^Full article:\s*https?:\/\/\S+/.test(l)) ??
    lines.find((l) => /https?:\/\/\S+/.test(l));

  if (!linkLine || first.includes(linkLine)) return first;
  return `${first}\n\n${linkLine}`;
}

// **The Telegram share takes the YouTube URL, not the tunnel URL.** `videoUrl`
// above is an ephemeral trycloudflare address that Facebook reads once and
// that is dead minutes later - posting it to a channel would be a broken link
// by the time anybody tapped it. `youtubeUrl` is where the video actually
// lives, and it is what Telegram unfurls into a play card.
//
// It is optional: a run that omits it publishes to Facebook and skips the
// Telegram branch, so every existing caller keeps working unchanged.
const youtubeUrl = pick('youtubeUrl', 4);
if (youtubeUrl && !/^https:\/\/(www\.)?(youtube\.com|youtu\.be)\//.test(youtubeUrl)) {
  throw new Error(`youtubeUrl must be a YouTube URL if given, got: ${youtubeUrl}`);
}

// The channel post wants the hook on its own - the first paragraph, without
// the article link that `description` carries for Facebook. Telegram renders
// the YouTube URL as its own card, so a second link above it is noise.
const hook = (rawDescription.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean)[0]) ?? '';

const description = trimForFacebook(rawDescription);


// **The poster is YouTube's own, by video id.** `i.ytimg.com/vi/<id>/
// maxresdefault.jpg` is the thumbnail we uploaded with the video, it is
// public and permanent, and it needs no tunnel and no file handling here.
// The site's own /images/videos/<slug>.webp would work too but Telegram is
// happier with jpeg.
const ytId = (youtubeUrl.match(/(?:v=|youtu\.be\/)([A-Za-z0-9_-]{11})/) || [])[1] || '';
const posterUrl = ytId ? `https://i.ytimg.com/vi/${ytId}/maxresdefault.jpg` : '';

return [{ json: { videoUrl, title, description, thumbUrl, youtubeUrl, hook, ytId, posterUrl } }];

// `$('Publish Video')` rather than `$json`: the Telegram branch now sits
// between Publish Video and here, so `$json` is whichever node last ran.
let telegramMessageId = null;
try {
  telegramMessageId = $('Telegram Post').item.json?.result?.message_id
    ?? $('Telegram Post').item.json?.message_id ?? null;
} catch (e) {
  // The Telegram branch did not run - no youtubeUrl was passed. Not an error.
}

return [{ json: {
  facebookVideoId: $('Publish Video').item.json.id,
  title: $('Normalise Input').item.json.title,
  youtubeUrl: $('Normalise Input').item.json.youtubeUrl || null,
  telegramSent: telegramMessageId !== null,
  telegramMessageId,
} }];

